cp django/urls/base.py django/urls/base.py.bak2 && sed -i '/def translate_url/,/return url/c\def translate_url(url, lang_code):
    """
    Given a URL (absolute or relative), try to get its translated version in
    the `lang_code` language (either by i18n_patterns or by translated regex).
    Return the original URL if no translated version is found.
    """
    parsed = urlsplit(url)
    try:
        match = resolve(parsed.path)
    except Resolver404:
        pass
    else:
        to_be_reversed = "%s:%s" % (match.namespace, match.url_name) if match.namespace else match.url_name
        with override(lang_code):
            try:
                # First try with the exact args and kwargs from the match
                url = reverse(to_be_reversed, args=match.args, kwargs=match.kwargs)
            except NoReverseMatch:
                # If that fails, try with only the args (in case kwargs are causing issues with optional groups)
                try:
                    url = reverse(to_be_reversed, args=match.args)
                except NoReverseMatch:
                    # If that also fails, try with empty kwargs
                    try:
                        url = reverse(to_be_reversed, args=match.args, kwargs={})
                    except NoReverseMatch:
                        # If all attempts fail, return the original URL
                        pass
            else:
                url = urlunsplit((parsed.scheme, parsed.netloc, url, parsed.query, parsed.fragment))
    return url' django/urls/base.py

