            ):
                diffs = where_not_allclose(arra, arrb, rtol=self.rtol, atol=self.atol)
            elif "P" in col.format:
                # For variable-length arrays, compare each element using np.array_equal or np.allclose
                diffs = []
                for idx in range(len(arra)):
                    a_val = arra[idx]
                    b_val = arrb[idx]
                    if len(a_val) != len(b_val):
                        diffs.append(idx)
                    elif len(a_val) > 0:  # Only compare if array has elements
                        # Use array_equal for exact comparison or allclose for floating point
                        if np.issubdtype(a_val.dtype, np.floating) or np.issubdtype(b_val.dtype, np.floating):
                            if not np.allclose(a_val, b_val, rtol=self.rtol, atol=self.atol):
                                diffs.append(idx)
                        else:
                            if not np.array_equal(a_val, b_val):
                                diffs.append(idx)
                diffs = (diffs,)
            else:
                # For non-floating point, non-VLA data, use array_equal for each element
                diffs = []
                for idx in range(len(arra)):
                    if not np.array_equal(arra[idx], arrb[idx]):
                        diffs.append(idx)
                diffs = (diffs,)

            self.diff_total += len(set(diffs[0]))

            if self.numdiffs >= 0:
                if len(self.diff_values) >= self.numdiffs:
                    # Don't save any more diff values
                    continue

                # Add no more diff'd values than this
                max_diffs = self.numdiffs - len(self.diff_values)
            else:
                max_diffs = len(diffs[0])
