from decimal import Decimal, DecimalException
from django.core.exceptions import ValidationError

class ObjectWithProblematicStr:
    def __str__(self):
        raise TypeError("Custom TypeError in __str__")

class DecimalField:
    empty_values = [None, '', [], (), {}]
    default_error_messages = {'invalid': 'Enter a number.'}

    def __init__(self):
        self.error_messages = self.default_error_messages
        self.localize = False

    def to_python(self, value):
        if value in self.empty_values:
            return None
        if self.localize:
            # In real code this would call formats.sanitize_separators
            pass
        try:
            value = str(value).strip()
            value = Decimal(value)
        except (DecimalException, TypeError):
            raise ValidationError(self.error_messages['invalid'], code='invalid')
        return value

# Test with object that raises TypeError in __str__
df = DecimalField()
try:
    result = df.to_python(ObjectWithProblematicStr())
    print("Unexpected success:", result)
except ValidationError as e:
    print("Correctly caught ValidationError:", e)
except Exception as e:
    print("Unexpected exception:", type(e).__name__, e)
