# Read the file
with open('astropy/io/fits/diff.py', 'r') as file:
    lines = file.readlines()

# Find the start of the TableDataDiff._diff method
start_idx = None
for i, line in enumerate(lines):
    if 'class TableDataDiff' in line:
        for j in range(i, len(lines)):
            if 'def _diff' in lines[j]:
                start_idx = j
                break
        if start_idx is not None:
            break

# Find and remove any existing initialization of diff_column_count
if start_idx is not None:
    # Look for lines that set diff_column_count in the first few lines of the method
    i = start_idx + 1
    while i < start_idx + 10:
        if i < len(lines) and 'self.diff_column_count' in lines[i]:
            del lines[i]
            # Don't increment i since we removed a line
        else:
            i += 1

    # Find the first line after the docstring
    for i in range(start_idx + 1, len(lines)):
        if lines[i].strip() and not lines[i].strip().startswith('"""'):
            # Insert after the first non-empty, non-docstring line
            insert_idx = i + 1
            lines.insert(insert_idx, '        self.diff_column_count = None\n')
            break

    # Write the changes back to the file
    with open('astropy/io/fits/diff.py', 'w') as file:
        file.writelines(lines)
    print("Successfully updated the file")
else:
    print("Could not find the TableDataDiff._diff method")
