import sys
import os

# Add the testbed directory to Python path
sys.path.insert(0, os.path.abspath('/testbed'))

# Configure Django settings
from django.conf import settings
if not settings.configured:
    settings.configure(
        DEBUG=True,
        INSTALLED_APPS=['testapp'],
        TEMPLATES=[{
            'BACKEND': 'django.template.backends.django.DjangoTemplates',
            'DIRS': [],
            'APP_DIRS': True,
            'OPTIONS': {
                'context_processors': [],
            },
        }]
    )

# Setup Django
import django
django.setup()

from django.template import Template, Context

# Test cases
tests = [
    # Test 1: Keyword with default value
    {
        'name': 'hello with greeting=hi',
        'template': '{% load test_tags %}{% hello greeting="hi" %}',
        'expected': 'hi world'
    },
    # Test 2: Multiple values for same keyword
    {
        'name': 'hi with multiple greeting values',
        'template': '{% load test_tags %}{% hi greeting="hi" greeting="hello" %}',
        'expected_error': "'hi' received multiple values for keyword argument 'greeting'"
    },
    # Test 3: Function with both positional and keyword-only args
    {
        'name': 'mixed_args with keyword override',
        'template': '{% load test_tags %}{% mixed_args "test" keyword="override" %}',
        'expected': 'test override'
    },
    # Test 4: Function with varargs and kwargs
    {
        'name': 'varargs_func with kwargs',
        'template': '{% load test_tags %}{% varargs_func key="value" %}',
        'expected': "args: (), kwargs: {'key': 'value'}"
    }
]

# Run tests
for i, test in enumerate(tests, 1):
    print(f"\nTest {i}: {test['name']}")
    try:
        t = Template(test['template'])
        c = Context()
        result = t.render(c)
        if 'expected' in test:
            if result == test['expected']:
                print(f"Success: Got expected result '{result}'")
            else:
                print(f"Failed: Expected '{test['expected']}' but got '{result}'")
        else:
            print(f"Failed: Expected error but got result '{result}'")
    except Exception as e:
        if 'expected_error' in test:
            error_str = str(e)
            if test['expected_error'] in error_str:
                print(f"Success: Got expected error '{error_str}'")
            else:
                print(f"Failed: Expected error '{test['expected_error']}' but got '{error_str}'")
        else:
            print(f"Failed: Got unexpected error '{str(e)}'")

print("\nAll tests completed.")
