mkdir -p /testbed/reproduction && cat > /testbed/reproduction/reproduce.py << 'EOL'
# Script to reproduce the OuterRef issue in exclude() or ~Q()
from django.db import models
from django.db.models import Exists, OuterRef

class Category(models.Model):
    name = models.CharField(max_length=100)

class Tag(models.Model):
    name = models.CharField(max_length=100)
    category = models.ForeignKey(Category, on_delete=models.CASCADE)

class Item(models.Model):
    name = models.CharField(max_length=100)
    tags = models.ManyToManyField(Tag)

class Number(models.Model):
    value = models.IntegerField()

def test_exists_exclude():
    # This works - filter with Exists and OuterRef
    qs = Number.objects.annotate(
        foo=Exists(
            Item.objects.filter(tags__category_id=OuterRef('pk'))
        )
    ).filter(foo=True)
    print("Filter query SQL:", qs.query)

    # This should work but crashes - exclude with Exists and OuterRef
    try:
        qs = Number.objects.annotate(
            foo=Exists(
                Item.objects.exclude(tags__category_id=OuterRef('pk'))
            )
        ).filter(foo=True)
        print("Exclude query SQL:", qs.query)
    except Exception as e:
        print("Exclude query error:", str(e))

    # This should work but crashes - filter with negated Q and OuterRef
    try:
        qs = Number.objects.annotate(
            foo=Exists(
                Item.objects.filter(~Q(tags__category_id=OuterRef('pk')))
            )
        ).filter(foo=True)
        print("Negated Q query SQL:", qs.query)
    except Exception as e:
        print("Negated Q query error:", str(e))

test_exists_exclude()
EOL

