from django.db import models
from django import forms

class ArticleManager(models.Manager):
    def get_queryset(self):
        qs = super().get_queryset()
        return qs.filter(archived=False)

class Article(models.Model):
    title = models.CharField(max_length=100)
    archived = models.BooleanField(default=False)
    # Don't include archived articles by default.
    objects = ArticleManager()

    def __str__(self):
        return self.title

class FavoriteArticle(models.Model):
    article = models.ForeignKey(Article, on_delete=models.CASCADE)

class FavoriteArticleForm(forms.ModelForm):
    class Meta:
        model = FavoriteArticle
        fields = '__all__'

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        # Use the base manager instead of the default manager to allow archived articles.
        self.fields['article'].queryset = Article._base_manager.all()

# Create the database schema
from django.test import TestCase

class TestFavoriteArticleForm(TestCase):
    def setUp(self):
        # Create test data
        self.active_article = Article.objects.create(title="Active Article", archived=False)
        self.archived_article = Article.objects.create(title="Archived Article", archived=True)

    def test_form_with_archived_article(self):
        # Test the form with an archived article
        form_data = {'article': self.archived_article.pk}
        form = FavoriteArticleForm(data=form_data)
        print(f"Form is valid: {form.is_valid()}")
        if not form.is_valid():
            print(f"Form errors: {form.errors}")

        # Also test with active article for comparison
        form_data_active = {'article': self.active_article.pk}
        form_active = FavoriteArticleForm(data=form_data_active)
        print(f"Form with active article is valid: {form_active.is_valid()}")
        if not form_active.is_valid():
            print(f"Form with active article errors: {form_active.errors}")

# Run the test
if __name__ == '__main__':
    # Create a test runner
    from django.test.runner import DiscoverRunner
    runner = DiscoverRunner(verbosity=2)
    # Run the specific test method
    test_suite = runner.build_suite([__file__])
    runner.run_suite(test_suite)
